def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
        N (int): The size of the grid (N x N).
        grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
            the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
            The list is terminated by a tuple with all zeros.

    Returns:
        int: The maximum sum of values collected on the two paths.
    """

    # Initialize a 2D array to store the values for each grid cell
    values = [[0] * N for _ in range(N)]

    # Set the initial values for the first and last grid cells
    values[0][0] = grid_values[0][2]
    values[N - 1][N - 1] = grid_values[N * N - 1][2]

    # Fill in the values for the remaining grid cells
    for i in range(1, N):
        for j in range(1, N):
            values[i][j] = max(
                values[i - 1][j],
                values[i][j - 1],
                values[i - 1][j - 1],
                grid_values[i * N + j][2],
            )

    # Find the two paths that maximize the sum of values collected
    max_sum = 0
    for i in range(N):
        for j in range(N):
            for k in range(i, N):
                for l in range(j, N):
                    if i == 0 and j == 0:
                        continue
                    elif i == N - 1 and j == N - 1:
                        continue
                    elif i == k and j == l:
                        continue
                    else:
                        max_sum = max(max_sum, values[i][j] + values[k][l])

    return max_sum

