        # Calculate the Manhattan distance between the pairs
        distance = abs(Xi - Pi) + abs(Yi - Qi)

        # Increment the number of chatting pairs that can be separated by adding an aisle in each possible position
        for row, col in itertools.product(range(M), range(N)):
            # Check if the chatting pair can be separated by adding an aisle in the current row and column
            if (row, col) not in num_separations:
                num_separations[(row, col)] = 0
            if distance > (row + col):
                num_separations[(row, col)] += 1

    # Select the most effective positions for aisles
    for i in range(K + L):
        # Select the row and column index with the maximum number of chatting pairs that can be separated
        max_separations = max(num_separations.values())
        for row, col in num_separations:
            if num_separations[(row, col)] == max_separations:
                # Add the row and column index to the list
                row_indices.append(row)
                col_indices.append(col)

                # Remove the selected row and column index from the dictionary
                del num_separations[(row, col)]
                break

    # Return the optimal row and column indices for the aisles
